const (
	// DefaultReadHeaderTimeout bounds how long a client may take to send its
	// request headers, so a connection that dribbles them out cannot hold a
	// server goroutine forever. The request body is deliberately left untimed
	// because a 50MB upload on a slow link is legitimate.
	DefaultReadHeaderTimeout = 15 * time.Second
	// DefaultIdleTimeout closes keep-alive connections that stopped sending
	// requests instead of keeping them open indefinitely.
	DefaultIdleTimeout = 60 * time.Second
	// DefaultShutdownTimeout is how long in-flight requests get to finish once a
	// shutdown signal arrives; a synchronous mask waits for the upstream call, so
	// it needs more than the upstream timeout to drain cleanly.
	DefaultShutdownTimeout = 45 * time.Second
)

type Config struct {
	Server  ServerConfig
	Upstage UpstageConfig
	Limits  LimitsConfig
	Storage StorageConfig
	Debug   DebugConfig
	Mock    MockConfig
}

type ServerConfig struct {
	Address       string
	PublicBaseURL string
	// ReadHeaderTimeout and IdleTimeout bound how long a connection may stay open
	// without making progress. ShutdownTimeout bounds the graceful drain.
	ReadHeaderTimeout time.Duration
	IdleTimeout       time.Duration
	ShutdownTimeout   time.Duration
}

type UpstageConfig struct {
	BaseURL    string
	AuthMode   string
	AuthToken  string
	AllowHosts []string
	Timeout    time.Duration
	Model      string
	Lang       string
	Schema     string
	Verbose    bool
}

type LimitsConfig struct {
	MaxFileSizeBytes  int64
	MaxPages          int
	MaxConcurrentJobs int
	MaxConcurrentSync int
	// SyncQueueWait is how long a synchronous request waits for a free processing
	// slot before it is rejected as busy. Zero rejects it right away.
	SyncQueueWait  time.Duration
	SupportedMIMEs []string
}

type StorageConfig struct {
	RootDir string
	// JobRetention is how long a finished job keeps its stored files. Zero disables
	// the cleanup and keeps everything.
	JobRetention time.Duration
}

type DebugConfig struct {
	EnableDebug bool
}

type MockConfig struct {
	EnableEmbeddedUpstageMock bool
}

func Load() (Config, error) {
	rootDir := envOrDefault("PII_MASKER_STORAGE_DIR", filepath.Join(".", "data"))
	// The listen address is read once so that the embedded mock upstream below and
	// the server config further down cannot drift apart.
	address := envOrDefault("PII_MASKER_ADDR", defaultAddress)
	baseURL := strings.TrimSpace(os.Getenv("PII_MASKER_UPSTAGE_BASE_URL"))
	mockEnabled := envBool("PII_MASKER_ENABLE_EMBEDDED_UPSTAGE_MOCK", false)
